<script setup>
import { computed,onMounted,ref } from "vue";import {useRouter} from "vue-router";import {getCart,getStokvelFeatures,updateCartItem,removeCartItem,confirmCurrentOrder} from "../services/api.js";import {readCartState,saveCartState,clearCartState} from "../composables/useCartState.js";
const router=useRouter(),items=ref([]),stokvel=ref(null),loading=ref(true),error=ref(""),busyItemId=ref(null),confirmingOrder=ref(false),showConfirm=ref(false),walletBalance=ref(0),deliveryAddress=ref("");const total=computed(()=>items.value.reduce((s,i)=>s+Number(i.subtotal||0),0)),itemCount=computed(()=>items.value.reduce((s,i)=>s+Number(i.quantity||0),0)),remainingBalance=computed(()=>Number(walletBalance.value-total.value));function sync(){saveCartState({items:items.value,order:null,stokvel:stokvel.value})}
async function load(){loading.value=true;error.value="";const saved=readCartState();if(saved?.items?.length){items.value=saved.items;stokvel.value=saved.stokvel||null}try{const[c,f]=await Promise.all([getCart(),getStokvelFeatures()]);items.value=c.items||[];stokvel.value=c.stokvel||stokvel.value;walletBalance.value=Number(f.wallet?.available_balance||0);sync()}catch(e){if(saved?.items?.length){items.value=saved.items;stokvel.value=saved.stokvel||null}else error.value=e.response?.data?.message||"Unable to load your group basket."}finally{loading.value=false}}
async function change(item,n){const q=Number(item.quantity)+n;if(q<=0)return remove(item);await setQty(item,q)}async function setQty(item,q){busyItemId.value=item.order_item_id;try{const r=await updateCartItem(item.order_item_id,q);Object.assign(item,r.item);sync()}catch(e){error.value=e.response?.data?.message||"Unable to update that item."}finally{busyItemId.value=null}}async function remove(item){busyItemId.value=item.order_item_id;try{await removeCartItem(item.order_item_id);items.value=items.value.filter(x=>x.order_item_id!==item.order_item_id);items.value.length?sync():clearCartState()}catch(e){error.value=e.response?.data?.message||"Unable to remove that item."}finally{busyItemId.value=null}}
function openConfirm(){error.value="";if(!items.value.length)return;if(remainingBalance.value<0){error.value=`The group wallet has ${money(walletBalance.value)} available, but this basket costs ${money(total.value)}.`;return}showConfirm.value=true}async function confirm(){if(confirmingOrder.value)return;if(!deliveryAddress.value.trim()){error.value="Delivery address is required.";return}confirmingOrder.value=true;error.value="";try{await confirmCurrentOrder(deliveryAddress.value.trim());clearCartState();showConfirm.value=false;router.push("/order-history")}catch(e){error.value=e.response?.data?.message||"The group order could not be confirmed."}finally{confirmingOrder.value=false}}function money(v){return`R ${Number(v||0).toFixed(2)}`}function shop(){router.push("/catalogue")}onMounted(load)
</script>
<template><main class="cart-page"><section class="cart-container"><div class="cart-heading"><div><p class="eyebrow">GROUP BASKET</p><h1>Your shared basket</h1><p class="intro" v-if="stokvel">Shopping together with <strong>{{stokvel.stokvel_name}}</strong>.</p></div><button class="secondary-button continue-shopping" type="button" @click="shop"><span aria-hidden="true">←</span> Continue shopping</button></div><div v-if="error" class="message error-message">{{error}}</div><div v-if="loading" class="state-card">Loading your group basket…</div><div v-else-if="!items.length" class="empty-card"><div class="empty-icon">🛒</div><h2>Your basket is empty</h2><p>Add products from the catalogue and they will be shared with your Stokvel.</p><button class="primary-button" @click="shop">Browse catalogue</button></div><div v-else class="cart-layout"><section class="items-card"><div class="card-header"><h2>Basket items</h2><p>{{itemCount}} item{{itemCount===1?'':'s'}} in the shared basket</p></div><article v-for="item in items" :key="item.order_item_id" class="cart-item"><div class="product-image-wrap"><img v-if="item.image_url" :src="item.image_url" :alt="item.product_name"/><span v-else>🛒</span></div><div class="item-details"><h3>{{item.product_name}}</h3><p>{{item.supplier_name}}</p><strong>{{money(item.unit_price)}} each</strong></div><div class="quantity-control"><button :disabled="busyItemId===item.order_item_id" @click="change(item,-1)">−</button><span>{{item.quantity}}</span><button :disabled="busyItemId===item.order_item_id" @click="change(item,1)">+</button></div><strong class="item-total">{{money(item.subtotal)}}</strong><button class="remove-button" :disabled="busyItemId===item.order_item_id" @click="remove(item)">Remove</button></article></section><aside class="summary-card"><p class="eyebrow">GROUP WALLET CHECKOUT</p><h2>Shared purchase</h2><div class="summary-line"><span>Items</span><strong>{{itemCount}}</strong></div><div class="summary-line"><span>Group wallet</span><strong>{{money(walletBalance)}}</strong></div><div class="summary-line"><span>Total</span><strong>{{money(total)}}</strong></div><div class="summary-line"><span>After purchase</span><strong :class="{negative:remainingBalance<0}">{{money(remainingBalance)}}</strong></div><button class="primary-button confirm-button" :disabled="!items.length||remainingBalance<0" @click="openConfirm">Review group purchase</button><p class="summary-note">Member cards are only used for contributions. This order spends the shared wallet.</p></aside></div></section><div v-if="showConfirm" class="modal-backdrop"><section class="confirm-modal"><button class="close" @click="showConfirm=false">×</button><p class="eyebrow">CONFIRM GROUP PURCHASE</p><h2>Spend from the Group Wallet?</h2><p>This order costs <strong>{{money(total)}}</strong> and will be deducted from <strong>{{stokvel?.stokvel_name||'your Stokvel'}}</strong>'s wallet.</p><div class="confirm-stats"><span>Wallet now<strong>{{money(walletBalance)}}</strong></span><span>After order<strong>{{money(remainingBalance)}}</strong></span></div><label class="address-label">DELIVERY ADDRESS</label><input v-model="deliveryAddress" class="address-input" placeholder="Enter the group delivery address"/><div class="modal-actions"><button class="secondary-button" @click="showConfirm=false">Cancel</button><button class="primary-button" :disabled="confirmingOrder||!deliveryAddress.trim()" @click="confirm">{{confirmingOrder?'Processing…':'Confirm & spend wallet'}}</button></div></section></div></main></template>
<style scoped>
.cart-page{min-height:100vh;padding:36px 24px 60px;background:var(--sw-page-background);color:var(--sw-page-text)}.cart-container{max-width:1180px;margin:auto}.cart-heading{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-bottom:28px}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--sw-purple-700)}h1{font-size:42px;margin:0}h2,h3{color:var(--sw-page-text)}.intro,p{color:var(--sw-page-text-muted);line-height:1.6}.secondary-button,.primary-button,.remove-button{padding:13px 20px;border-radius:999px;font-weight:800;cursor:pointer}.secondary-button{border:1px solid var(--sw-input-border);background:var(--sw-page-surface);color:var(--sw-page-text)}.continue-shopping{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:46px;padding:12px 18px;border-color:var(--sw-purple-700);color:var(--sw-purple-700);white-space:nowrap;transition:transform .2s ease,background .2s ease,color .2s ease,box-shadow .2s ease}.continue-shopping span{font-size:18px;line-height:1}.continue-shopping:hover{background:var(--sw-purple-700);color:#fff;transform:translateY(-1px);box-shadow:0 8px 20px rgba(121,93,137,.2)}.continue-shopping:focus-visible{outline:3px solid rgba(121,93,137,.28);outline-offset:3px}.primary-button{border:0;background:var(--sw-purple-700);color:#fff}.message,.state-card,.empty-card,.items-card,.summary-card{border:1px solid var(--sw-input-border);border-radius:22px;background:var(--sw-page-surface);box-shadow:var(--sw-card-shadow)}.message{padding:14px;margin-bottom:18px;color:#b42318}.state-card,.empty-card{padding:50px;text-align:center}.cart-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:22px}.items-card{overflow:hidden}.card-header{padding:24px;border-bottom:1px solid var(--sw-input-border)}.card-header h2{margin:0}.card-header p{margin:5px 0 0}.cart-item{display:grid;grid-template-columns:70px 1fr auto auto auto;align-items:center;gap:16px;padding:18px 22px;border-bottom:1px solid var(--sw-input-border)}.product-image-wrap{width:70px;height:70px;border-radius:12px;background:var(--sw-page-background);display:grid;place-items:center;overflow:hidden}.product-image-wrap img{width:100%;height:100%;object-fit:contain}.item-details h3{margin:0 0 4px}.item-details p{margin:0 0 4px;font-size:12px}.quantity-control{display:flex;gap:8px;align-items:center;border:1px solid var(--sw-input-border);border-radius:999px;padding:4px}.quantity-control button{width:30px;height:30px;border:0;border-radius:50%;cursor:pointer}.remove-button{border:0;background:transparent;color:#b42318;font-size:12px}.summary-card{padding:26px;position:sticky;top:90px}.summary-line{display:flex;justify-content:space-between;padding:14px 0;border-bottom:1px solid var(--sw-input-border)}.negative{color:#b42318!important}.confirm-button{width:100%;margin-top:12px}.summary-note{font-size:12px}.modal-backdrop{position:fixed;inset:0;background:rgba(0,0,0,.58);display:grid;place-items:center;padding:20px;z-index:1000}.confirm-modal{width:min(540px,100%);padding:30px;border-radius:24px;background:var(--sw-page-surface);border:1px solid var(--sw-input-border);position:relative}.close{position:absolute;right:15px;top:12px;border:0;background:none;font-size:28px;cursor:pointer}.confirm-stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:20px 0}.confirm-stats span{padding:14px;border-radius:12px;background:var(--sw-page-background);color:var(--sw-page-text-muted)}.confirm-stats strong{display:block;color:var(--sw-page-text);margin-top:5px}.address-label{display:block;font-size:11px;font-weight:800;letter-spacing:.1em;margin:15px 0 7px}.address-input{width:100%;box-sizing:border-box;padding:14px;border-radius:12px;border:1px solid var(--sw-input-border);background:var(--sw-page-background);color:var(--sw-page-text)}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}@media(max-width:900px){.cart-layout{grid-template-columns:1fr}.summary-card{position:static}}@media(max-width:700px){.cart-heading{flex-direction:column;align-items:stretch}.continue-shopping{align-self:flex-start}.cart-item{grid-template-columns:56px 1fr}.quantity-control,.item-total,.remove-button{grid-column:2;justify-self:start}.modal-actions{flex-direction:column}.modal-actions>*{width:100%}}
</style>
